const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
const header=$('#siteHeader'),progress=$('#progressBar'),navLinks=$$('.nav-link'),indicator=$('#navIndicator');
let lastY=0,ticking=false;
function setIndicator(el){if(!el||innerWidth<901)return;const track=$('#navTrack').getBoundingClientRect(),box=el.getBoundingClientRect();indicator.style.left=`${box.left-track.left}px`;indicator.style.width=`${box.width}px`}
function onScroll(){const y=scrollY,max=document.documentElement.scrollHeight-innerHeight;progress.style.width=`${max?y/max*100:0}%`;header.classList.toggle('hidden',y>lastY&&y>100);lastY=Math.max(0,y);ticking=false}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(onScroll);ticking=true}},{passive:true});
addEventListener('resize',()=>setIndicator($('.nav-link.active')));setIndicator($('.nav-link.active'));
navLinks.forEach(link=>{link.addEventListener('mouseenter',()=>setIndicator(link));link.addEventListener('focus',()=>setIndicator(link))});$('#navTrack').addEventListener('mouseleave',()=>setIndicator($('.nav-link.active')));
const menu=$('#mobileMenu'),toggle=$('#menuToggle');function closeMenu(){toggle.classList.remove('open');toggle.setAttribute('aria-expanded','false');menu.classList.remove('open');menu.setAttribute('aria-hidden','true')}
toggle.addEventListener('click',()=>{const open=!menu.classList.contains('open');toggle.classList.toggle('open',open);toggle.setAttribute('aria-expanded',open);menu.classList.toggle('open',open);menu.setAttribute('aria-hidden',!open)});$$('a',menu).forEach(a=>a.addEventListener('click',closeMenu));
const reveals=$$('.reveal,.mask-reveal');document.documentElement.classList.add('motion-ready');const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');io.unobserve(entry.target)}}),{threshold:.04,rootMargin:'80px 0px'});reveals.forEach(el=>io.observe(el));setTimeout(()=>reveals.forEach(el=>el.classList.add('visible')),1400);
const sections=$$('main section[id]');const sectionIO=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){const id=e.target.id==='about'?'about':e.target.id;const match=$(`.nav-link[href="#${id}"]`);if(match){navLinks.forEach(n=>n.classList.remove('active'));match.classList.add('active');setIndicator(match)}}}),{rootMargin:'-36% 0px -55%'});sections.forEach(s=>sectionIO.observe(s));
const serviceImage=$('#serviceImage'),caption=$('#serviceCaption');$$('.service-row').forEach(row=>row.addEventListener('mouseenter',()=>swapService(row)));$$('.service-row').forEach(row=>row.addEventListener('focus',()=>swapService(row)));function swapService(row){if(row.classList.contains('active'))return;$$('.service-row').forEach(r=>r.classList.remove('active'));row.classList.add('active');$('.service-visual').classList.add('changing');setTimeout(()=>{serviceImage.src=row.dataset.image;serviceImage.alt=row.dataset.alt;caption.textContent=row.dataset.caption;serviceImage.onload=()=>$('.service-visual').classList.remove('changing')},170)}
const video=$('#siteVideo');const videoIO=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&matchMedia('(prefers-reduced-motion: no-preference)').matches)video.play().catch(()=>{});else video.pause()}),{threshold:.55});videoIO.observe(video);
const process=$('#processTrack');new IntersectionObserver(([e])=>{if(e.isIntersecting)e.target.classList.add('active')},{threshold:.35}).observe(process);
const projects={wall:{image:'assets/wall_clean.webp',kicker:'Precast walls',title:'A strong property boundary',text:'Precast wall panels and columns configured for a practical perimeter solution.'},cottage:{image:'assets/cottage_build.webp',kicker:'Cottages',title:'Structure taking shape',text:'A supplied precast cottage system shown during the construction stage.'},installation:{image:'assets/wall_dark.webp',kicker:'Supply + installation',title:'Installed to follow the site',text:'A long precast wall fitted along an existing property boundary.'},finish:{image:'assets/flyer.webp',kicker:'Walls + paving',title:'Finished applications',text:'Precast boundaries and paving used together around a completed property.'}};
const projectModal=$('#projectModal');$$('.project').forEach(btn=>btn.addEventListener('click',()=>{const p=projects[btn.dataset.project];$('#modalImage').src=p.image;$('#modalImage').alt=p.title;$('#modalKicker').textContent=p.kicker;$('#modalTitle').textContent=p.title;$('#modalText').textContent=p.text;projectModal.showModal()}));
const filmModal=$('#filmModal'),modalVideo=$('#modalVideo');function openFilm(){video.pause();filmModal.showModal();modalVideo.play().catch(()=>{})}$('#openFilm').addEventListener('click',openFilm);$('#videoFrame').addEventListener('click',openFilm);
$$('.media-modal').forEach(modal=>{modal.querySelector('.modal-close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});modal.addEventListener('close',()=>{if(modal===filmModal)modalVideo.pause()})});
$('#quoteForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const msg=`Hello EK Precast Solutions, I'd like a quote for ${data.get('service')}. My project is located in ${data.get('location')}.\n\nName: ${data.get('name')}\nPhone: ${data.get('phone')}\nMessage: ${data.get('message')||'No additional message.'}`;open(`https://wa.me/263777811584?text=${encodeURIComponent(msg)}`,'_blank','noopener')});
onScroll();
